  "Du får <b>{0}</b> nu. Betala tillbaka <b>{1}</b> (lånet + {2} % ränta) senast <b>{3}</b> så får du tillbaka möbeln. Annars behåller pantbanken den.": "Te llevas <b>{0}</b> ahora. Devuelve <b>{1}</b> (el préstamo + {2} % de interés) como tarde <b>{3}</b> y recuperarás el mueble. Si no, se lo queda la casa de empeños.",
