  "Du får maten på en bricka och sätter dig vid ett bord eller i fönstret med utsikt över havet. Mättnaden och energin kommer medan du äter – och när allt är uppätet blir du gladare!": "Te dan la comida en una bandeja y te sientas a una mesa o junto a la ventana con vistas al mar. Mientras comes te vas llenando y recuperas energía – ¡y cuando te lo terminas todo te pones más contento!",
  "Du får maten på en bricka och sätter dig vid ett ledigt bord eller vid fönstret. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Te dan la comida en una bandeja y te sientas en una mesa libre o junto a la ventana. La saciedad y la energía llegan mientras comes – ¡solo si estás sentado!",
