  "💬 Alla djur här är ungar. De växer av mat, lek, en leksak och rätt toalett – tidigast unga efter 3 dagar och vuxna efter en vecka.": "💬 Todos los animales de aquí son crías. Crecen con comida, juegos, un juguete y el baño adecuado: jóvenes como pronto a los 3 días y adultos al cabo de una semana.",
  "💬 Djuren har en liten mätare ovanför sig: hjärtat är glädje och skålen är hunger.": "💬 Los animales tienen un pequeño indicador encima: el corazón es la alegría y el cuenco es el hambre.",
  "💬 Har du en hane och en hona av samma art kan de bli kära – och få ungar!": "💬 Si tienes un macho y una hembra de la misma especie, pueden enamorarse… ¡y tener crías!",
  "💬 Hundar måste ut på promenad i koppel, annars blir det olyckor inne.": "💬 Los perros tienen que salir a pasear con correa; si no, hay accidentes en casa.",
  "💬 Kaniner jagar inga bollar – men de älskar att gnaga på en gnagmorot!": "💬 Los conejos no persiguen pelotas… ¡pero les encanta roer una zanahoria de juguete!",
  "💬 Kaniner trivs bäst i en bur med halm. Byt halm ibland så blir de glada.": "💬 Los conejos están mejor en una jaula con paja. Cámbiales la paja de vez en cuando y estarán contentos.",
  "💬 Katter behöver en kattlåda – och den måste tömmas ibland!": "💬 Los gatos necesitan un arenero… ¡y hay que vaciarlo de vez en cuando!",
  "💬 Katter gillar att klättra – ett klösträd gör dem gladare.": "💬 A los gatos les gusta trepar: un rascador los pone más contentos.",
  "💬 Maten: klicka på säcken hemma så bär du den, klicka sen på skålen så häller du upp.": "💬 La comida: en casa pulsa el saco para cogerlo y luego pulsa el cuenco para servirla.",
